mapper.update:
UPDATE quant_paper_account
SET available_balance=available_balance-#{margin}, updated_at=UTC_TIMESTAMP()
WHERE id=#{accountId} AND available_balance>=#{margin}

UPDATE quant_paper_account
SET available_balance=available_balance+#{margin}, updated_at=UTC_TIMESTAMP()
WHERE id=#{accountId}

UPDATE quant_paper_account
SET unrealized_pnl=unrealized_pnl+#{pnl}-#{oldPnl}, updated_at=UTC_TIMESTAMP()
WHERE credential_id=#{credentialId}

